"""Job Factory for Testing."""

class JobFactory:
    """Factory for creating Job test objects."""

    @staticmethod
    def create(
        title="Software Engineer",
        company="Tech Corp",
        requirements=None,
        experience_years=3
    ):
        """Create a Job dict."""
        return {
            "title": title,
            "company": company,
            "requirements": requirements or ["Python", "AWS"],
            "experience_years": experience_years,
        }

